package server

import (
	"testing"
	"time"
)

func TestDefaults(t *testing.T) {
	s := NewServer()
	if s.Host != "localhost" {
		t.Fatalf("want localhost, got %q", s.Host)
	}
	if s.Port != 8080 {
		t.Fatalf("want 8080, got %d", s.Port)
	}
	if s.Timeout != 30*time.Second {
		t.Fatalf("want 30s, got %v", s.Timeout)
	}
}

func TestWithHost(t *testing.T) {
	s := NewServer(WithHost("0.0.0.0"))
	if s.Host != "0.0.0.0" {
		t.Fatalf("want 0.0.0.0, got %q", s.Host)
	}
}

func TestWithPort(t *testing.T) {
	s := NewServer(WithPort(9090))
	if s.Port != 9090 {
		t.Fatalf("want 9090, got %d", s.Port)
	}
}

func TestWithTimeout(t *testing.T) {
	s := NewServer(WithTimeout(60 * time.Second))
	if s.Timeout != 60*time.Second {
		t.Fatalf("want 60s, got %v", s.Timeout)
	}
}

func TestCombinedOptions(t *testing.T) {
	s := NewServer(WithHost("example.com"), WithPort(443), WithTimeout(10*time.Second))
	if s.Host != "example.com" || s.Port != 443 || s.Timeout != 10*time.Second {
		t.Fatalf("unexpected config: %+v", s)
	}
}

